INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('610dbbc1-0a06-5ec4-a034-df18e1091e75', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 60, 60, 'A small ball A of mass 2.0 g hangs from a support on an insulating thread. A second small ball B, carrying +40 nC and held on an insulating rod, is brought up level with A. A swings away and comes to rest with its thread at 20° to the vertical, with the centres of A and B 5.0 cm apart, as shown. Calculate the charge on A, in coulombs. Use k = 9.0 × 10⁹ N·m²/C² and take g = 9.8 N/kg.', 'diagram:coulomb-ch-fixed-unequal-charge', 4, 'numeric'::answer_type, '4.954e-8', 'C', 0.05, false, 'Free-body diagram for the hanging ball: its weight mg acts vertically down, the tension T acts along the thread towards the support, and the electric force Fe acts horizontally along the line of centres. In equilibrium the components balance: T sinθ = Fe (horizontal) and T cosθ = mg (vertical). Dividing removes T: Fe = mg tanθ. Step 1: mg = 2.0 × 10⁻³ kg × 9.8 N/kg = 0.0196 N. Step 2: Fe = 0.0196 × tan20° = 0.0196 × 0.364 = 0.00713 N. Step 3: the charges are NOT equal, so rearrange F = kqAqB/r² for qA alone: qA = Fe r²/(k qB) = 0.00713 × 0.050² ÷ (9.0 × 10⁹ × 40 × 10⁻⁹) = 4.95 × 10⁻⁸ C (about 50 nC). A is repelled by a positive charge, so A is positive too. (The tension is T = mg/cos20° = 0.0209 N, a little more than the weight.) Common mistake: copying Q38’s q = √(Fe r²/k) — that assumes equal charges, and here only qA is unknown. Also convert 5.0 cm to 0.050 m and 40 nC to 40 × 10⁻⁹ C before substituting.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('ab526dbb-1b44-5412-95e9-9ea7a64d31c7', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 61, 61, 'A 0.50 g pith ball hangs on an insulating thread. An identical ball on an insulating rod is brought up level with it. Each ball carries +12 nC. The hanging ball swings away and comes to rest with its thread at 15° to the vertical, as shown. Calculate the distance between the centres of the two balls, in metres. Use k = 9.0 × 10⁹ N·m²/C² and take g = 9.8 N/kg.', 'diagram:coulomb-ch-fixed-find-separation', 4, 'numeric'::answer_type, '0.03142', 'm', 0.05, false, 'Free-body diagram for the hanging ball: its weight mg acts vertically down, the tension T acts along the thread towards the support, and the electric force Fe acts horizontally along the line of centres. In equilibrium the components balance: T sinθ = Fe (horizontal) and T cosθ = mg (vertical). Dividing removes T: Fe = mg tanθ. Step 1: mg = 0.50 × 10⁻³ × 9.8 = 0.00490 N. Step 2: Fe = mg tan15° = 0.00490 × 0.268 = 0.00131 N. Step 3: rearrange F = kq²/r² for r: r = √(kq²/Fe) = √(9.0 × 10⁹ × (12 × 10⁻⁹)² ÷ 0.00131) = √(9.87 × 10⁻⁴) = 0.0314 m, about 3.1 cm. The angle being measured to the vertical is what makes the horizontal component T sinθ, and T itself is not mg: T = mg/cos15° = 0.00507 N. Common mistake: writing Fe = mg sinθ (that is the component of the weight along an incline, not this balance) — it gives r = 0.0320 m. Another is forgetting the square root at the last step.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('a4a65e50-e2bd-583f-9204-e10e9d2b0f1f', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 62, 62, 'A 1.5 g ball carrying +30 nC hangs on an insulating thread. A ball carrying −25 nC on an insulating rod is moved so that, when the hanging ball comes to rest, the two are level with their centres 4.0 cm apart, as shown. Calculate the angle the thread makes with the vertical, in degrees. Use k = 9.0 × 10⁹ N·m²/C² and take g = 9.8 N/kg.', 'diagram:coulomb-ch-fixed-attract-angle', 4, 'numeric'::answer_type, '16.01', '°', 0.05, false, 'The charges are unlike, so the hanging ball is ATTRACTED and swings towards the rod, not away from it. Free-body diagram for the hanging ball: its weight mg acts vertically down, the tension T acts along the thread towards the support, and the electric force Fe acts horizontally towards the other ball. In equilibrium the components balance: T sinθ = Fe (horizontal) and T cosθ = mg (vertical). Dividing removes T: tanθ = Fe/mg. Step 1: Fe = k|qAqB|/r² = 9.0 × 10⁹ × 30 × 10⁻⁹ × 25 × 10⁻⁹ ÷ 0.040² = 0.00422 N. Step 2: mg = 1.5 × 10⁻³ × 9.8 = 0.0147 N. Step 3: tanθ = 0.00422 ÷ 0.0147 = 0.287, so θ = 16.0°. Common mistake: using sinθ = Fe/mg, which gives 16.7°. Fe and mg are the two legs of the right-angled force triangle and T is the hypotenuse, so their ratio is tanθ.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('3b157254-7958-5b9d-821c-2f5a6b80464d', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 63, 63, 'Two identical small balls, each of mass 2.0 g, hang from the same point on an insulating rod by threads 0.50 m long. They are given equal charges and repel until each thread makes 10° with the vertical, as shown. Calculate the charge on each ball, in coulombs. Use k = 9.0 × 10⁹ N·m²/C² and take g = 9.8 N/kg.', 'diagram:coulomb-ch-pair-find-charge', 4, 'numeric'::answer_type, '1.076e-7', 'C', 0.05, false, 'Free-body diagram for either ball: weight mg vertically down, tension T along its thread towards the support, and the electric force Fe horizontally, directly away from the other ball. In equilibrium the components balance: T sinθ = Fe (horizontal) and T cosθ = mg (vertical). Dividing removes T: Fe = mg tanθ. Step 1 (geometry): each ball is L sinθ from the vertical through the support, so the separation is r = 2L sinθ = 2 × 0.50 × sin10° = 0.174 m. Step 2: Fe = mg tan10° = 0.0196 × 0.176 = 0.00346 N. Step 3: Fe = kq²/r², so q = r√(Fe/k) = 0.174 × √(0.00346 ÷ 9.0 × 10⁹) = 1.08 × 10⁻⁷ C. Each thread pulls with T = mg/cos10° = 0.0199 N. Common mistake: using r = L sinθ = 0.0868 m, which is the distance from ONE ball to the vertical, not the gap between the balls — it gives half the charge, 5.38 × 10⁻⁸ C.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('c9cbe366-3f62-54e5-bb11-7b8b4c3e9381', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 64, 64, 'Two small balls, each carrying +50 nC, hang from the same point on insulating threads 0.25 m long. In equilibrium their centres are 6.0 cm apart, as shown. The masses of the balls are not given. Calculate the tension in each thread, in newtons. Use k = 9.0 × 10⁹ N·m²/C².', 'diagram:coulomb-ch-pair-tension-no-mass', 4, 'numeric'::answer_type, '0.05208', 'N', 0.05, false, 'Free-body diagram for either ball: weight mg vertically down, tension T along its thread towards the support, and the electric force Fe horizontally, directly away from the other ball. Step 1 (geometry): half the separation, 0.030 m, is the side opposite θ in a right-angled triangle whose hypotenuse is the 0.25 m thread, so sinθ = 0.030 ÷ 0.25 = 0.120 and θ = 6.89°. Step 2: Fe = kq²/r² = 9.0 × 10⁹ × (50 × 10⁻⁹)² ÷ 0.060² = 0.00625 N. Step 3: only the tension has a horizontal component to balance Fe: T sinθ = Fe, so T = 0.00625 ÷ 0.120 = 0.0521 N. (The vertical balance then gives the mass you were not told: m = T cosθ/g = 5.28 g.) Common mistake: reaching for T = mg/cosθ when m is unknown, or dividing Fe by tanθ — Fe/tanθ = 0.0517 N is the WEIGHT mg, not the tension.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('80dc454c-b779-5fd8-b2c7-0d3c3d8937bc', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 65, 65, 'Two balls of equal mass hang from the same point on threads of equal length. Ball A carries +20 nC and ball B carries +80 nC, four times as much. When they come to rest, how do the two thread angles compare, and why?', 'diagram:coulomb-ch-pair-unequal-charges-why', 4, 'multiple_choice'::answer_type, 'The angles are equal: by Newton’s third law A and B feel electric forces of the same size, and with equal masses and threads their force diagrams are identical', NULL, NULL, false, 'The force between A and B is ONE interaction: F = k qA qB / r² uses the product of the charges, so it is the same size on each ball (Newton’s third law — equal and opposite). Free-body diagram for each ball: mg down, T along the thread, Fe horizontal and away from the other ball. Both balls have the same mg and the same Fe, so Fe = mg tanθ gives the same θ for both — the arrangement is symmetric even though the charges are not. Swapping the charges, or making them +40 nC each (same product), would leave the angles unchanged. Unequal angles need unequal MASSES. Common mistake: thinking the bigger charge “feels” a bigger force or “gives out” a bigger force — each charge feels the same force, because the force depends on both charges together.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('4e2dd2bd-161e-5696-96f3-d1b9fb211168', '80dc454c-b779-5fd8-b2c7-0d3c3d8937bc', 'B’s thread makes the larger angle, because B carries four times the charge', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('549a47d9-52a4-5f2e-827a-0839842f0509', '80dc454c-b779-5fd8-b2c7-0d3c3d8937bc', 'A’s thread makes the larger angle, because B’s bigger charge pushes A harder than A pushes B', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('a960dd44-239a-561c-b62a-474e89d8d112', '80dc454c-b779-5fd8-b2c7-0d3c3d8937bc', 'The angles are equal: by Newton’s third law A and B feel electric forces of the same size, and with equal masses and threads their force diagrams are identical', 'C', true, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('63fd50a6-a8fb-5436-976f-1c857f6632ab', '80dc454c-b779-5fd8-b2c7-0d3c3d8937bc', 'The angles are equal only once the balls have touched and shared their charge equally', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b3be52e6-ff32-5ab4-9d00-65de82f59bbb', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 66, 66, 'Two balls of mass 2.0 g hang from the same point on threads 0.60 m long. One carries charge q and the other 3q. In equilibrium each thread makes 9.0° with the vertical, as shown. Calculate q, in coulombs. Use k = 9.0 × 10⁹ N·m²/C² and take g = 9.8 N/kg.', 'diagram:coulomb-ch-pair-q-and-3q', 4, 'numeric'::answer_type, '6.365e-8', 'C', 0.05, false, 'The angles are equal even though the charges are not: the electric force on each ball is the same (Newton’s third law) and the masses are equal. Free-body diagram for either ball: weight mg vertically down, tension T along its thread towards the support, and the electric force Fe horizontally, directly away from the other ball. In equilibrium the components balance: T sinθ = Fe (horizontal) and T cosθ = mg (vertical). Dividing removes T: Fe = mg tanθ. Step 1: r = 2L sinθ = 2 × 0.60 × sin9.0° = 0.188 m. Step 2: Fe = mg tan9.0° = 0.0196 × 0.158 = 0.00310 N. Step 3: Fe = k(q)(3q)/r² = 3kq²/r², so q = r√(Fe/3k) = 0.188 × √(0.00310 ÷ (3 × 9.0 × 10⁹)) = 6.37 × 10⁻⁸ C, and the other ball carries 3q = 1.91 × 10⁻⁷ C. Common mistake: writing F = kq²/r² as if both charges were q (giving 1.10 × 10⁻⁷ C), or adding the charges (q + 3q) instead of multiplying them.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('1591ba8c-c6ae-58ef-a3c9-c77aa4981a43', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 67, 67, 'Two balls carrying equal charges hang from the same point on insulating threads whose lengths have been adjusted so that the balls hang LEVEL with each other, as shown. Ball 1 has mass 2.0 g and its thread makes 30° with the vertical. Ball 2 has mass 6.0 g. Calculate the angle ball 2’s thread makes with the vertical, in degrees.', 'diagram:coulomb-ch-pair-unequal-masses-angle', 4, 'numeric'::answer_type, '10.89', '°', 0.05, false, 'Because the balls are level, the line joining them — and so the electric force — is horizontal on both. By Newton’s third law that force has the same size Fe on each ball. Free-body diagram for either ball: weight mg vertically down, tension T along its thread towards the support, and the electric force Fe horizontally, directly away from the other ball. For each ball Fe = mg tanθ. Step 1: ball 1 gives Fe = m₁g tan30° = 2.0 × 10⁻³ × 9.8 × 0.577 = 0.0113 N. Step 2: the same Fe acts on ball 2: tanθ₂ = Fe/(m₂g) = 0.0113 ÷ (0.0588) = 0.192, so θ₂ = 10.9°. Shortcut: equal Fe means m₁ tanθ₁ = m₂ tanθ₂, so tanθ₂ = tan30° ÷ 3. g cancels, so its value does not matter. Common mistake: dividing the ANGLE by 3 (30° ÷ 3 = 10°). It is tanθ that scales with 1/m, not θ. Another is thinking the heavier ball feels a smaller electric force — it feels the same force, it is just harder to push sideways.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('c74dbb19-c19a-5202-b553-2e828de07a43', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 68, 68, 'Two identical balls, each of mass 1.0 g and carrying +20 nC, hang from the same point on threads 0.80 m long. Using the small-angle approximation sinθ ≈ tanθ ≈ x/2L, where x is the separation of the balls, show that x³ = 2kq²L/(mg), and calculate x in metres. State why the approximation is justified. Use k = 9.0 × 10⁹ N·m²/C² and take g = 9.8 N/kg.', 'diagram:coulomb-ch-pair-small-angle-x', 5, 'numeric'::answer_type, '0.08377', 'm', 0.05, false, 'Free-body diagram for either ball: weight mg vertically down, tension T along its thread towards the support, and the electric force Fe horizontally, directly away from the other ball. In equilibrium the components balance: T sinθ = Fe (horizontal) and T cosθ = mg (vertical). Dividing removes T: Fe = mg tanθ. Step 1 (exact condition): with r = x = 2L sinθ, kq²/x² = mg tanθ. Step 2 (approximation): for a small angle tanθ ≈ sinθ = x/2L, so kq²/x² = mg x/(2L), which rearranges to x³ = 2kq²L/(mg). Step 3: x³ = 2 × 9.0 × 10⁹ × (20 × 10⁻⁹)² × 0.80 ÷ (1.0 × 10⁻³ × 9.8) = 5.88 × 10⁻⁴ m³, so x = 0.0838 m. Step 4 (justify): θ ≈ x/2L = 0.0524 rad ≈ 3.0°. At this angle tanθ and sinθ differ by only 0.1%, so the approximation is excellent. Solving the exact equation numerically gives x = 0.08373 m, the same to 3 s.f. Common mistake: taking the square root instead of the cube root at the end — x appears on both sides, giving x³, not x². Another is using the thread length L as the separation.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('13d0e7c0-dd54-5291-9df5-2b94ddae2cb0', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 69, 69, 'Two identical 2.0 g balls, each carrying +0.20 µC, hang from one point on threads 0.15 m long. A student uses x³ = 2kq²L/(mg) and gets a separation of 17.7 cm. Which judgement of the student’s method is correct? Use k = 9.0 × 10⁹ N·m²/C² and take g = 9.8 N/kg.', 'diagram:coulomb-ch-pair-approx-validity', 5, 'multiple_choice'::answer_type, 'The approximation is not valid: x/2L implies θ ≈ 36°, where tanθ is about 24% bigger than sinθ, so the true separation is noticeably smaller — about 16.6 cm', NULL, NULL, false, 'Free-body diagram for either ball: weight mg vertically down, tension T along its thread towards the support, and the electric force Fe horizontally, directly away from the other ball. The exact balance is Fe = mg tanθ with Fe = kq²/(2L sinθ)², and the approximation replaces tanθ by sinθ = x/2L. Check an approximation by putting its answer back in. Step 1: x = 17.7 cm means sinθ = x/2L = 0.589, so θ ≈ 36°. Step 2: at that angle tanθ = 0.728 but sinθ = 0.589 — they differ by about 24%, so “sinθ ≈ tanθ” is not a fair assumption. Step 3: solving kq²/(2L sinθ)² = mg tanθ exactly (by trial and improvement, or numerically) gives θ = 33.6° and x = 16.6 cm. The approximation over-estimates x by 6.3%. A useful rule of thumb: below about 10° the error is under 1%. Option D is false — the separation can be up to 2L. Common mistake: judging an approximation by whether the ANSWER looks reasonable instead of checking the angle it implies.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ac64756b-1dd4-5f0a-a562-b84e09eb53e4', '13d0e7c0-dd54-5291-9df5-2b94ddae2cb0', 'The approximation is valid, because the separation is smaller than the thread length', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('08693271-f2f0-52d0-8766-fb59cfc068b8', '13d0e7c0-dd54-5291-9df5-2b94ddae2cb0', 'The approximation is not valid: x/2L implies θ ≈ 36°, where tanθ is about 24% bigger than sinθ, so the true separation is noticeably smaller — about 16.6 cm', 'B', true, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('de188f4d-87da-5b4b-b05c-43c52c96b0d6', '13d0e7c0-dd54-5291-9df5-2b94ddae2cb0', 'The approximation is valid for any angle below 45°, because tanθ and sinθ are equal until then', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('6b1997b4-0e95-58ff-9502-c15d14c45e19', '13d0e7c0-dd54-5291-9df5-2b94ddae2cb0', 'The approximation is not valid, because the separation can never be more than the thread length L', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('1c4ff513-b955-5fbb-8d95-e7d5b7c9b1d1', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 70, 70, 'Two identical small conducting balls of mass 1.2 g hang from the same point on insulating threads 0.50 m long. Ball A carries +60 nC and ball B carries +20 nC. The balls are brought together so that they touch, then released. Calculate their new separation in equilibrium, in metres. Use k = 9.0 × 10⁹ N·m²/C² and take g = 9.8 N/kg.', 'diagram:coulomb-ch-pair-touch-share', 5, 'numeric'::answer_type, '0.1068', 'm', 0.05, false, 'Step 1 (charge sharing): identical conductors share the total charge equally: (60 + 20) ÷ 2 = 40 nC each. Charge is conserved — the total is still 80 nC. Step 2: the product q₁q₂ goes from 60 × 20 = 1200 to 40 × 40 = 1600 (nC)², up by a factor 4/3, so the balls end up FURTHER apart even though no charge was added. Free-body diagram for either ball: weight mg vertically down, tension T along its thread towards the support, and the electric force Fe horizontally, directly away from the other ball. In equilibrium kq²/x² = mg tanθ with x = 2L sinθ. Step 3 (small angles, tanθ ≈ x/2L): x³ = 2kq²L/(mg) = 2 × 9.0 × 10⁹ × (40 × 10⁻⁹)² × 0.50 ÷ (1.2 × 10⁻³ × 9.8), so x = 0.107 m. Step 4 (check): θ ≈ x/2L = 0.107 rad ≈ 6.1°, small, so the approximation holds — the exact solution is x = 0.1068 m (before touching it was 0.0970 m). Common mistake: assuming the separation cannot change because the TOTAL charge is unchanged. The force depends on the product of the charges, which is largest when the charge is shared equally.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('ba8f4066-5cc4-53bb-af13-ca310bd6c306', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 71, 71, 'Two identical balls carrying equal charges hang from the same point on threads 0.30 m long, each thread at 12° to the vertical. Ball A is touched with an identical uncharged ball, which is then taken away. Calculate the new angle each thread makes with the vertical, in degrees. (The masses and charges are not needed.)', 'diagram:coulomb-ch-pair-neutral-touch', 5, 'numeric'::answer_type, '9.525', '°', 0.05, false, 'Step 1 (charge sharing): A shares its charge equally with the identical neutral ball, so A keeps q/2 while B keeps q. The product q₁q₂ halves. Both balls still feel equal forces (Newton’s third law), so the angles stay equal. Free-body diagram for either ball: weight mg vertically down, tension T along its thread towards the support, and the electric force Fe horizontally, directly away from the other ball. Step 2: with x = 2L sinθ, the balance kq₁q₂/x² = mg tanθ becomes kq₁q₂ = 4L²mg sin²θ tanθ. Everything except q₁q₂ is fixed, so sin²θ tanθ is proportional to q₁q₂. Step 3: sin²θ tanθ must halve: before it was sin²12° × tan12° = 0.00919, now it must be 0.00459. Trial and improvement (or a calculator solver) gives θ = 9.52°. Small-angle check: x ∝ (q₁q₂)^⅓, so sinθ falls by a factor of 0.5^⅓ = 0.794, giving 9.50° — the same to 3 s.f. Common mistake: halving the angle (6°) or the separation. Halving q₁q₂ does not halve the force in the end, because the balls move closer and the force grows back.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('488a2416-e450-524a-8ff9-ea11e4963da6', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 72, 72, 'Two identical charged balls hang from the same point on long threads, with a small angle between the threads. The charge on EACH ball is doubled. A student says: “Coulomb’s law gives four times the force, so the balls end up twice as far apart.” What actually happens to the separation?', 'diagram:coulomb-ch-pair-double-both-trap', 5, 'multiple_choice'::answer_type, 'It increases by a factor of about 1.59: as the balls move apart the force falls again, and the new balance (x³ ∝ q₁q₂) gives 4^⅓', NULL, NULL, false, 'The trap is treating r as fixed. Free-body diagram: mg down, T along the thread, Fe = kq₁q₂/x² horizontal. The balance is Fe = mg tanθ ≈ mg x/2L for small angles. Step 1: substitute Fe: kq₁q₂/x² = mg x/2L, so x³ = 2kq₁q₂L/(mg) — x is proportional to the CUBE ROOT of q₁q₂. Step 2: doubling both charges multiplies q₁q₂ by 4, so x grows by 4^⅓ = 1.59, not 2. Step 3: the force ends up only 1.59 times bigger too (F ≈ mg x/2L), not 4 times — moving apart has weakened it. The student’s “double” is wrong twice over: 4× force would not double x even at fixed angle, because F ∝ 1/x². Common mistake: applying F ∝ q₁q₂ while forgetting that x — and the angle — change until a new equilibrium is reached.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('44c58e92-6e2c-5a2c-b49e-33fe92625e49', '488a2416-e450-524a-8ff9-ea11e4963da6', 'It doubles, as the student says', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('0b286bbb-4467-541e-84f2-d8759a3fa343', '488a2416-e450-524a-8ff9-ea11e4963da6', 'It becomes four times as large, because the force is four times as large', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('717ee7aa-ae14-5267-963a-a5a66fae5996', '488a2416-e450-524a-8ff9-ea11e4963da6', 'It increases by a factor of about 1.59: as the balls move apart the force falls again, and the new balance (x³ ∝ q₁q₂) gives 4^⅓', 'C', true, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('bce0b392-92cf-5a03-87bf-20e431486c02', '488a2416-e450-524a-8ff9-ea11e4963da6', 'It does not change, because the tension increases to balance the bigger force', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('5d586d3d-57ec-59a3-a46b-bf6c2f37cc0e', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 73, 73, 'Two identical charged balls hang from the same point, with a small angle between the threads. The charge on ONE ball is doubled and they settle in a new equilibrium. By what factor has the electric force between them changed?', 'diagram:coulomb-ch-pair-double-one-force', 5, 'multiple_choice'::answer_type, '×1.26 (2^⅓), because the balls move apart until the weaker force at the new separation balances again', NULL, NULL, false, 'Free-body diagram for either ball: mg down, T along the thread, Fe horizontal. In equilibrium Fe = mg tanθ, and for small angles tanθ ≈ x/2L, so Fe ≈ mg x/2L — the force is proportional to the separation. Step 1: from kq₁q₂/x² = mg x/2L, x³ ∝ q₁q₂. Doubling one charge doubles q₁q₂, so x grows by 2^⅓. Step 2: Fe ∝ x, so the force also grows by 2^⅓ = 1.26 — not by 2. Had the separation been held fixed, the force would have doubled, but here the balls are free to move. Option D confuses “equilibrium” with “unchanged”: the weight is unchanged but the angle, the tension and the electric force all increase. Common mistake: using F ∝ q₁q₂ on its own when the separation is not held fixed.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('2f921908-c298-59ec-93fe-8b80d675d708', '5d586d3d-57ec-59a3-a46b-bf6c2f37cc0e', '×4, because force is proportional to charge squared', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('ca418b58-0384-5a9a-92cb-5423ff95e023', '5d586d3d-57ec-59a3-a46b-bf6c2f37cc0e', '×2, because force is proportional to the product of the charges', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('d7b60252-aec5-56fe-bb79-2c4f5ae38b7a', '5d586d3d-57ec-59a3-a46b-bf6c2f37cc0e', '×1.26 (2^⅓), because the balls move apart until the weaker force at the new separation balances again', 'C', true, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('8ae2e8c4-a8de-59af-a655-aa89632e6139', '5d586d3d-57ec-59a3-a46b-bf6c2f37cc0e', '×1, the force cannot change because the masses have not changed', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('3c7ead06-9c73-5507-be94-3d88ba261ab2', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 74, 74, 'A small ball of mass 5.0 g carrying +40 nC hangs at rest on an insulating thread. A second charged ball is fixed directly below it, with their centres 5.0 cm apart, as shown. Calculate the tension in the thread (a) when the lower ball carries +40 nC and (b) when it carries −40 nC. Enter your answer to (b), in newtons. Use k = 9.0 × 10⁹ N·m²/C² and take g = 9.8 N/kg.', 'diagram:coulomb-ch-vertical-tension', 4, 'numeric'::answer_type, '0.05476', 'N', 0.05, false, 'Free-body diagram: every force is vertical here — weight mg down, tension T up, and the electric force Fe either up (repulsion from below) or down (attraction towards the ball below). Step 1: mg = 5.0 × 10⁻³ × 9.8 = 0.0490 N. Fe = kq₁q₂/r² = 9.0 × 10⁹ × (40 × 10⁻⁹)² ÷ 0.050² = 0.00576 N, the same size in both cases. Step 2 (a): like charges REPEL, so Fe pushes the hanging ball up and helps the thread: T + Fe = mg, T = 0.0490 − 0.00576 = 0.0432 N. Step 3 (b): unlike charges ATTRACT, so Fe pulls down along with the weight: T = mg + Fe = 0.0490 + 0.00576 = 0.0548 N. Common mistake: always adding Fe to the weight. Decide the direction from the signs first: a like charge below pushes UP, an unlike charge below pulls DOWN.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('4bb9b25b-9f04-590c-9d30-fa4ea5ebb572', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 75, 75, 'A 2.0 g ball hangs on an insulating thread directly above a small sphere fixed on an insulating stand. The sphere carries +0.15 µC and the centres are 4.0 cm apart, as shown. What charge must the hanging ball carry for the tension in the thread to fall to zero? Give the magnitude in coulombs and state its sign. Use k = 9.0 × 10⁹ N·m²/C² and take g = 9.8 N/kg.', 'diagram:coulomb-ch-vertical-levitation', 4, 'numeric'::answer_type, '2.323e-8', 'C', 0.05, false, 'Free-body diagram: weight mg down, tension T up, electric force Fe vertical. T = 0 means Fe alone holds the ball up, so Fe must point UP — a repulsion — and the ball’s charge must be POSITIVE, like the sphere’s. Step 1: mg = 2.0 × 10⁻³ × 9.8 = 0.0196 N. At T = 0, Fe = mg. Step 2: kqQ/r² = mg, so q = mg r²/(kQ) = 0.0196 × 0.040² ÷ (9.0 × 10⁹ × 0.15 × 10⁻⁶) = 2.32 × 10⁻⁸ C (about 23.2 nC), positive. Step 3 (evaluate): vertically this balance is stable — if the ball drops a little, r falls and Fe rises, pushing it back. Sideways it is not: once the thread is slack, a small nudge lets the repulsion push the ball off to one side. That is why the thread is needed. Common mistake: giving a negative charge. An attraction from below would pull the ball DOWN and increase the tension.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('7b792049-38c8-56c5-b288-010a273be3c9', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 76, 76, 'A 0.80 g ball hangs on an insulating thread in a uniform horizontal electric field of strength 2.5 × 10⁴ N/C. The ball comes to rest with its thread at 14° to the vertical, displaced in the direction of the field, as shown. Calculate the charge on the ball, in coulombs, and state its sign. Take g = 9.8 N/kg.', 'diagram:coulomb-ch-field-find-q', 4, 'numeric'::answer_type, '7.819e-8', 'C', 0.05, false, 'Free-body diagram: weight mg down, tension T along the thread, and the electric force Fe = qE horizontal (along the field lines). This is the same force triangle as a ball repelled by a fixed charge, but here the horizontal force does not depend on distance — the field is uniform. In equilibrium the components balance: T sinθ = Fe (horizontal) and T cosθ = mg (vertical). Dividing removes T: Fe = mg tanθ. Step 1: mg = 0.80 × 10⁻³ × 9.8 = 0.00784 N, so Fe = 0.00784 × tan14° = 0.00195 N. Step 2: Fe = qE, so q = Fe/E = 0.00195 ÷ 2.5 × 10⁴ = 7.82 × 10⁻⁸ C. The ball is pushed IN the direction of the field, so the charge is positive. Common mistake: trying to use F = kq₁q₂/r² — there is no second point charge and no distance in a uniform field. F = qE links the force to the charge directly.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('efb56de5-3ff1-5333-a2b6-286b871b1fdd', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 77, 77, 'In an experiment to test Coulomb’s law, a 0.60 g charged ball hangs on an insulating thread and an identical charged ball on an insulating rod is held level with it at different separations r. The table shows r and the thread angle θ. (a) Calculate the electric force F for each reading. (b) Plot F against 1/r². (c) Find the gradient of the best straight line through the origin, in N·m², and state what it represents. (d) Suggest two sources of error and one improvement. Enter your gradient. Use k = 9.0 × 10⁹ N·m²/C² and take g = 9.8 N/kg.', 'diagram:coulomb-ch-fixed-data-analysis', 5, 'numeric'::answer_type, '3.586e-6', 'N·m²', 0.05, false, 'Free-body diagram for the hanging ball (each reading): weight mg down, tension T along the thread, electric force Fe horizontal, away from the fixed ball. Balancing components (T sinθ = Fe, T cosθ = mg) gives Fe = mg tanθ, written F below. (a) mg = 0.60 × 10⁻³ × 9.8 = 0.00588 N, so F = 0.00588 × tanθ: 3.0 cm → 0.00397 N, 4.0 cm → 0.00226 N, 5.0 cm → 0.00147 N, 6.0 cm → 9.84 × 10⁻⁴ N, 8.0 cm → 5.66 × 10⁻⁴ N. (b) Plotting F (y) against 1/r² (x): (1110 m⁻², 0.00397 N), (625 m⁻², 0.00226 N), (400 m⁻², 0.00147 N), (278 m⁻², 9.84 × 10⁻⁴ N), (156 m⁻², 5.66 × 10⁻⁴ N) — the points lie close to a straight line through the origin, so F ∝ 1/r², as Coulomb’s law predicts. (c) The best line through the origin has gradient 3.59 × 10⁻⁶ N·m². Since F = (kq₁q₂)(1/r²), the gradient is kq₁q₂. For equal charges q = √(gradient/k) = 2.00 × 10⁻⁸ C, about 20 nC each. (d) Sources of error: air currents make the ball swing, so θ is hard to read to better than ±0.5° (a large fractional error at the smallest angles), charge leaks away into humid air during the experiment so later readings are too small, and r is measured between centres that are hard to locate. Improvements: shield the apparatus in a draught-proof box, work quickly in dry air (or recharge before each reading), and read θ and r from a photograph against a scale. Common mistake: plotting F against r (a curve) or against 1/r (not straight), or reading the gradient as k alone — it is kq₁q₂.', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b003201f-a2c8-5a4c-96d6-9238c46f6ce5', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 78, 78, 'Two identical 1.0 g balls with equal charges hang from one point on threads 0.20 m long. Each thread makes 35° with the vertical, as shown. What is the charge on each ball? Use k = 9.0 × 10⁹ N·m²/C² and take g = 9.8 N/kg.', 'diagram:coulomb-ch-pair-mcq-mistakes', 4, 'multiple_choice'::answer_type, '2.00 × 10⁻⁷ C', NULL, NULL, false, 'Free-body diagram for either ball: weight mg vertically down, tension T along its thread towards the support, and the electric force Fe horizontally, directly away from the other ball. In equilibrium the components balance: T sinθ = Fe (horizontal) and T cosθ = mg (vertical). Dividing removes T: Fe = mg tanθ. Step 1: r = 2L sinθ = 2 × 0.20 × sin35° = 0.229 m. Step 2: Fe = mg tan35° = 0.00980 × 0.700 = 0.00686 N. Step 3: q = r√(Fe/k) = 2.00 × 10⁻⁷ C. Where the other options come from: 1.00 × 10⁻⁷ C uses r = L sinθ (one ball to the vertical, half the gap), 1.75 × 10⁻⁷ C uses the thread length as the separation, and 1.81 × 10⁻⁷ C uses Fe = mg sinθ instead of mg tanθ. Common mistake: any of those three — draw the geometry and the force triangle before substituting.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('9c1b9c93-aa4b-51d2-877d-23f12be85f1d', 'b003201f-a2c8-5a4c-96d6-9238c46f6ce5', '1.00 × 10⁻⁷ C', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('13acb003-7fd6-5685-b7c7-7d0f5c2303f5', 'b003201f-a2c8-5a4c-96d6-9238c46f6ce5', '1.75 × 10⁻⁷ C', 'B', false, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('18805c90-684c-5128-b05d-69727995bf57', 'b003201f-a2c8-5a4c-96d6-9238c46f6ce5', '1.81 × 10⁻⁷ C', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('e26fc0b4-5e5c-5ac0-881a-8ea857990f7d', 'b003201f-a2c8-5a4c-96d6-9238c46f6ce5', '2.00 × 10⁻⁷ C', 'D', true, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('57ed8393-afa2-5466-a13d-997660f6ee22', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 79, 79, 'Two identical balls, each of mass 1.0 g and carrying +0.15 µC, hang from the same point on insulating threads 0.20 m long. (a) Draw a free-body diagram for one ball and explain why the two threads make equal angles θ with the vertical. (b) Show that kq²/(4L² sin²θ) = mg tanθ. (c) Use the small-angle approximation to estimate the separation x of the balls. (d) Solve the equation in (b) by trial and improvement, use it to find the true separation to 3 significant figures, and evaluate the approximation in (c). Enter your answer to (d), in metres. Use k = 9.0 × 10⁹ N·m²/C² and take g = 9.8 N/kg.', 'diagram:coulomb-ch-extended-exact-separation', 5, 'numeric'::answer_type, '0.1934', 'm', 0.02, false, '(a) Free-body diagram for either ball: weight mg vertically down, tension T along its thread towards the support, and the electric force Fe horizontally, directly away from the other ball. The balls have equal masses, and the electric force on each has the same size (Newton’s third law), so the two force diagrams are mirror images and the angles are equal. (b) Horizontally T sinθ = Fe and vertically T cosθ = mg, so Fe = mg tanθ. The separation is r = 2L sinθ, so Fe = kq²/(2L sinθ)² = kq²/(4L² sin²θ) and therefore kq²/(4L² sin²θ) = mg tanθ. (c) With sinθ ≈ tanθ ≈ x/2L: x³ = 2kq²L/(mg) = 0.00827 m³, so x ≈ 0.202 m, which implies sinθ = x/2L = 0.505 and θ ≈ 30.4° — not a small angle. (d) Left side minus right side at θ = 28°: 5.32 × 10⁻⁴ N (positive: the electric force is still bigger than mg tanθ), at 29°: −4.75 × 10⁻⁵ N (negative), so θ lies between. Narrowing down gives θ = 28.9°, so x = 2L sinθ = 2 × 0.20 × sin28.9° = 0.193 m (and T = mg/cosθ = 0.0112 N). The approximation over-estimates x by 4.5%: at about 29° tanθ is already 14% bigger than sinθ. It is fine for a first estimate (and a good starting point for the trial and improvement) but not for an answer to 3 s.f. Common mistake: in (b), writing r = L sinθ or r = L. In (d), stopping at the small-angle value — this part asks for the exact solution.', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('def0ff03-266f-51bf-bd7f-97b0bce67f55', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 80, 80, 'A 1.2 g ball carrying +45 nC hangs on an insulating thread between two vertical charged plates, which produce a uniform horizontal electric field. The thread makes 18° with the vertical. (a) Draw and label the free-body diagram. (b) Calculate the field strength E. (c) Calculate the tension in the thread. (d) The field strength is doubled. A student predicts the angle will double to 36°. Evaluate this prediction by calculating the new angle. Enter your answer to (d), in degrees. Take g = 9.8 N/kg.', 'diagram:coulomb-ch-extended-field-double', 5, 'numeric'::answer_type, '33.02', '°', 0.05, false, '(a) Free-body diagram: weight mg vertically down, tension T along the thread, electric force Fe = qE horizontal, towards the negative plate (the ball is positive). (b) Fe = mg tan18° = 1.2 × 10⁻³ × 9.8 × 0.325 = 0.00382 N, so E = Fe/q = 0.00382 ÷ 45 × 10⁻⁹ = 84900 N/C. (c) T = mg/cos18° = 0.0118 ÷ 0.951 = 0.0124 N (or √((mg)² + Fe²), the same). (d) Doubling E doubles Fe (the field is uniform, so the force does not depend on where the ball ends up). Then tanθ doubles: tanθ = 2 × 0.325 = 0.650, so θ = 33.0°, not 36°. The prediction is wrong because θ is not proportional to Fe — tanθ is. (The new tension is 0.0140 N.) Common mistake: doubling the angle, or assuming the force changes as the ball moves, which is true near a point charge but not in a uniform field.', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('3654ae4c-b6fe-55c6-8997-4ddcca7784b0', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 81, 81, 'Two identical conducting balls of mass 2.0 g hang from one point on threads 0.50 m long and are given equal charges. Their centres settle 12.0 cm apart. (a) Calculate the charge on each ball. (b) Each ball is touched with an identical uncharged ball. Predict the new separation. (c) Ten minutes later the measured separation is 6.8 cm. Suggest why it is less than your prediction. (d) Estimate the charge left on each ball. Enter your answer to (b), in metres. Use k = 9.0 × 10⁹ N·m²/C² and take g = 9.8 N/kg.', 'diagram:coulomb-ch-extended-leakage', 5, 'numeric'::answer_type, '0.07571', 'm', 0.05, false, 'Free-body diagram for either ball: weight mg vertically down, tension T along its thread towards the support, and the electric force Fe horizontally, directly away from the other ball. In equilibrium the components balance: T sinθ = Fe (horizontal) and T cosθ = mg (vertical). Dividing removes T: Fe = mg tanθ. (a) sinθ = (x/2)/L = 0.060 ÷ 0.50 = 0.12, θ = 6.89°. Fe = mg tanθ = 0.0196 × 0.121 = 0.00237 N, and q = x√(Fe/k) = 0.120 × √(0.00237 ÷ 9.0 × 10⁹) = 6.16 × 10⁻⁸ C. (b) Each ball keeps q/2, so q₁q₂ falls to a quarter. For small angles x³ ∝ q₁q₂, so x = 12.0 cm × (1/4)^⅓ = 7.56 cm. Solving the exact balance kq²/(2L sinθ)² = mg tanθ with q = 3.08 × 10⁻⁸ C gives x = 0.0757 m — the angle is small, so the two agree. (c) The balls lose charge to the air (leakage, faster when the air is humid) and through the threads and supports if they are not perfect insulators, so the force — and the separation — keep falling. (d) With x = 6.8 cm: sinθ = 0.034 ÷ 0.50, θ = 3.90°, Fe = mg tanθ = 0.00134 N, so q = 0.068 × √(Fe/k) = 2.62 × 10⁻⁸ C each — 85% of the charge they had straight after being touched. Common mistake: in (b), halving the separation (because the charge halved) or quartering it (because the force quartered). x ∝ (q₁q₂)^⅓ for small angles.', 9) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('2bdb582c-fac1-51d0-a1e7-316dc25332ca', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 82, 82, 'Two small balls carrying equal charges hang from the same point. Their thread lengths are adjusted so that the balls hang level, 6.0 cm apart. The lighter ball (3.0 g) hangs at 24° to the vertical and the heavier one at 15°. (a) Explain why the electric force on each ball has the same size, even though the angles differ. (b) Show that m₁ tanθ₁ = m₂ tanθ₂ and calculate the mass of the heavier ball. (c) Calculate the charge on each ball. (d) Calculate the tension in the heavier ball’s thread. Enter your answer to (b), in kilograms. Use k = 9.0 × 10⁹ N·m²/C² and take g = 9.8 N/kg.', 'diagram:coulomb-ch-extended-unequal-masses', 5, 'numeric'::answer_type, '0.004985', 'kg', 0.05, false, '(a) The two balls exert forces on each other — one interaction, so by Newton’s third law the forces are equal and opposite. Because the balls are level, both forces are horizontal. Free-body diagram for each ball: mg down, T along its thread, Fe horizontal and away from the other ball. (b) For each ball Fe = mg tanθ. The same Fe acts on both, so m₁g tanθ₁ = m₂g tanθ₂ and m₁ tanθ₁ = m₂ tanθ₂. Then m₂ = 3.0 g × tan24° ÷ tan15° = 3.0 × 0.445 ÷ 0.268 = 4.98 g = 0.00498 kg. (c) Fe = m₁g tan24° = 3.0 × 10⁻³ × 9.8 × 0.445 = 0.0131 N. With equal charges Fe = kq²/r², so q = 0.060 × √(0.0131 ÷ 9.0 × 10⁹) = 7.24 × 10⁻⁸ C. (d) T₂ = m₂g/cos15° = 0.0489 ÷ 0.966 = 0.0506 N (check: √((m₂g)² + Fe²) gives the same). Common mistake: assuming the heavier ball feels the smaller electric force. The forces are equal — the heavier ball simply needs a bigger sideways force to reach the same angle, so it hangs closer to the vertical. Note also that m ∝ 1/tanθ, not 1/θ.', 10) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('1457168a-3232-5be9-9f65-f79ed4355d39', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 83, 83, 'Charge qA = +4.0 µC is at x = 0 and qB = −1.0 µC is at x = 30 cm. A third charge qC = +2.0 µC is placed between them at x = 10 cm, as shown. Calculate the magnitude of the net electrostatic force on qC, in newtons, and give its direction. Use k = 9.0 × 10⁹ N·m²/C².', 'diagram:coulomb-ch-line-middle-net', 4, 'numeric'::answer_type, '7.65', 'N', 0.05, false, 'Take +x to the right and treat each pair separately. Step 1: qA and qC are both positive, so qA REPELS qC — to the right (+x): F = 9.0 × 10⁹ × 4.0 × 10⁻⁶ × 2.0 × 10⁻⁶ ÷ 0.10² = 7.20 N. Step 2: qB is negative, so qB ATTRACTS qC — towards qB, also to the right: F = 9.0 × 10⁹ × 1.0 × 10⁻⁶ × 2.0 × 10⁻⁶ ÷ 0.20² = 0.450 N. Step 3: both point the same way, so they ADD: 7.20 + 0.450 = 7.65 N, towards qB (+x). Common mistake: subtracting because the two charges are on opposite sides of qC. Work out each direction from the signs — here repulsion from the left and attraction to the right both push qC right. Also use 0.20 m (not 0.30 m) for qB to qC.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('379224c4-3c81-5e04-ad40-1500a075f939', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 84, 84, 'Charge qA = +4.0 µC is fixed at x = 0 and qB = −1.0 µC is fixed at x = 0.30 m. At what position x would a third charge feel zero net electrostatic force? Give x in metres, measured from qA.', 'diagram:coulomb-ch-line-zero-point', 5, 'numeric'::answer_type, '0.6', 'm', 0.05, false, 'Step 1 (where can it be?): between the charges, a test charge is pushed away from one and pulled towards the other — both forces point the same way, so they cannot cancel. To the left of qA it is always nearer the BIGGER charge, so qA’s force wins. The only possible region is to the right of qB, the smaller charge. Step 2: let the point be at x (> 0.30). The forces from qA and qB must have equal size: k(4.0 µC)q/x² = k(1.0 µC)q/(x − 0.30)². The test charge q and k cancel: 4(x − 0.30)² = x². Step 3: expand: 4x² − 2.4x + 0.36 = x², so 3x² − 2.4x + 0.36 = 0. The quadratic formula gives x = (2.4 ± √(1.44)) ÷ 6 = 0.200 m or 0.600 m. Step 4 (reject): x = 0.200 m is BETWEEN the charges, where the forces have equal size but point the same way — it is a root of the size equation, not a balance point. So x = 0.600 m, 0.30 m beyond qB. Check: 4.0 ÷ 0.60² = 11.1 and 1.0 ÷ 0.30² = 11.1. The answer does not depend on the sign or size of the third charge. Common mistake: keeping both roots, or taking the square root of only one side when solving.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('f5925c07-b158-58ff-bd9a-f16018cdfe13', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 85, 85, 'Two positive charges are fixed 0.90 m apart: q₁ = +2.0 nC at x = 0 and q₂ = +8.0 nC at x = 0.90 m. A small positive charge is placed on the line between them. At what distance from q₁ is the net force on it zero? Give your answer in metres.', 'diagram:coulomb-ch-line-between-like', 4, 'numeric'::answer_type, '0.3', 'm', 0.05, false, 'Step 1 (where?): between two LIKE charges the test charge is pushed in opposite directions, so a balance point exists between them — nearer the SMALLER charge. Step 2: at distance x from q₁: kq₁q/x² = kq₂q/(0.90 − x)². Cancel k and q: 2.0/x² = 8.0/(0.90 − x)². Step 3: both sides are positive squares, so take square roots: (0.90 − x)/x = √(8.0/2.0) = 2, giving 0.90 − x = 2x and x = 0.300 m from q₁. (Squaring out would give a second root, x = −0.90 m, outside the charges where both forces point the same way — rejected.) Common mistake: placing the balance point nearer the bigger charge, or at the midpoint. The force falls with distance squared, so the point sits where the distances are in the ratio √q₁ : √q₂ = 1 : 2.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('08fcab41-efe9-523b-b7e8-f40ae0f8f7e0', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 86, 86, 'In the previous arrangement (q₁ = +2.0 nC at x = 0, q₂ = +8.0 nC at x = 0.90 m), the two outer charges are now free to move. What charge q₃, placed at the balance point 0.30 m from q₁, would keep ALL THREE charges in equilibrium? Give q₃ in coulombs, including its sign.', 'diagram:coulomb-ch-line-three-equilibrium', 5, 'numeric'::answer_type, '-8.889e-10', 'C', 0.05, true, 'Step 1: q₃ is already balanced at x = 0.30 m whatever its value (k and q₃ cancelled in the previous question). Now q₁ and q₂ must also be balanced. Step 2 (sign): q₂ pushes q₁ to the left, so q₃ must PULL q₁ to the right — q₃ must be NEGATIVE. Step 3 (size, balance on q₁): k|q₁q₃|/0.30² = kq₁q₂/0.90², so |q₃| = q₂ × (0.30/0.90)² = 8.0 nC × 1/9 = 0.889 nC. Step 4 (check on q₂): attraction to q₃ = k × 8.0 × 0.889 ÷ 0.60² and repulsion from q₁ = k × 8.0 × 2.0 ÷ 0.90², both 19.8 k (nC²/m²) — balanced. So q₃ = −8.89 × 10⁻¹⁰ C. Common mistake: giving a positive q₃ (it would push q₁ and q₂ further apart), or using the distance 0.30 m for the q₁–q₂ pair instead of 0.90 m.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('a0385d9a-91ea-58ab-810c-7c31f58dcd02', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 87, 87, 'A small POSITIVE charge sits at the balance point between two fixed positive charges (as in the previous two questions), where the net force on it is zero. Is this equilibrium stable?', 'diagram:coulomb-ch-line-stability', 5, 'multiple_choice'::answer_type, 'Stable for a nudge along the line joining the charges, but unstable for a nudge at right angles to that line', NULL, NULL, false, 'Step 1 (along the line): nudge the charge towards q₁. It is now closer to q₁, whose repulsion grows, and further from q₂, whose repulsion falls, so the net force pushes it BACK — stable along the line. Step 2 (at right angles): nudge it slightly sideways. Both fixed charges repel it along lines that now point slightly AWAY from the axis, so their sideways components add and push it further out — unstable. So the equilibrium is stable in one direction only. (A negative charge at the same point would be the other way round: unstable along the line.) In fact no arrangement of fixed charges can hold a charge in stable equilibrium in every direction — this is Earnshaw’s theorem. Common mistake: checking only one direction of displacement, or assuming “zero force” means stable.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('707aefe1-8f40-5f5e-92b4-b6e218347b3e', 'a0385d9a-91ea-58ab-810c-7c31f58dcd02', 'Stable in every direction: whichever way it is nudged, it returns', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('50c0d0e7-b507-55de-b50d-20fb3c594a01', 'a0385d9a-91ea-58ab-810c-7c31f58dcd02', 'Stable for a nudge along the line joining the charges, but unstable for a nudge at right angles to that line', 'B', true, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('8180d6d2-6baf-5afc-948f-9dde741a85bb', 'a0385d9a-91ea-58ab-810c-7c31f58dcd02', 'Unstable along the line, but stable for a nudge at right angles to it', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('b7e2a0ca-96ad-5419-98aa-11171b646742', 'a0385d9a-91ea-58ab-810c-7c31f58dcd02', 'Neutral: the net force stays zero everywhere near the balance point', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('9a4d8397-75e5-519b-8102-32d36312f01d', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 88, 88, 'Four charges sit at the corners of a square of side 0.20 m, as shown: qA = +3.0 µC (top left), qB = −2.0 µC (top right), qC = +4.0 µC (bottom right) and qD = −1.0 µC (bottom left). Calculate the magnitude of the net electrostatic force on qA, in newtons. Use k = 9.0 × 10⁹ N·m²/C².', 'diagram:coulomb-ch-square-mixed', 5, 'numeric'::answer_type, '0.4843', 'N', 0.05, false, 'Take +x to the right and +y upwards, and work out each force on qA with its direction from the signs. Step 1: qB is negative, so it ATTRACTS qA along the top edge, +x: F = 9.0 × 10⁹ × 3.0 × 10⁻⁶ × 2.0 × 10⁻⁶ ÷ 0.20² = 1.35 N. Step 2: qD is negative, so it attracts qA down the left edge, −y: F = 9.0 × 10⁹ × 3.0 × 10⁻⁶ × 1.0 × 10⁻⁶ ÷ 0.20² = 0.675 N. Step 3: qC is positive and across the diagonal, r² = 0.20² + 0.20² = 0.080 m². It REPELS qA, up and to the left at 45°: F = 9.0 × 10⁹ × 3.0 × 10⁻⁶ × 4.0 × 10⁻⁶ ÷ 0.080 = 1.35 N, with components −0.955 N (x) and +0.955 N (y). Step 4: ΣFx = 1.35 − 0.955 = 0.395 N, ΣFy = −0.675 + 0.955 = 0.280 N. F = √(0.395² + 0.280²) = 0.484 N, at 35° above the +x direction. Common mistake: using 0.20 m for the diagonal (it is 0.20√2 m, so r² = 0.080 m²), or adding the three magnitudes as if they were in a line.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('2dcf800b-c9dc-5338-9a2e-eaebd319b0c1', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 89, 89, 'Charges sit at the corners of a 0.40 m × 0.30 m rectangle, as shown: P = +5.0 nC at the bottom left, +6.0 nC at the bottom right, −4.0 nC at the top left and −8.0 nC at the top right. Calculate the magnitude of the net electrostatic force on P, in newtons. Use k = 9.0 × 10⁹ N·m²/C².', 'diagram:coulomb-ch-rectangle-mixed', 5, 'numeric'::answer_type, '2.914e-6', 'N', 0.05, false, 'Take +x to the right and +y up, with P at the origin. The diagonal is √(0.40² + 0.30²) = 0.50 m (a 3-4-5 triangle). Step 1: +6.0 nC (0.40 m to the right) REPELS P, −x: F = 9.0 × 10⁹ × 5.0 × 10⁻⁹ × 6.0 × 10⁻⁹ ÷ 0.40² = 1.69 × 10⁻⁶ N. Step 2: −4.0 nC (0.30 m above) ATTRACTS P, +y: F = 9.0 × 10⁹ × 5.0 × 10⁻⁹ × 4.0 × 10⁻⁹ ÷ 0.30² = 2.00 × 10⁻⁶ N. Step 3: −8.0 nC (diagonal) attracts P towards it: F = 9.0 × 10⁹ × 5.0 × 10⁻⁹ × 8.0 × 10⁻⁹ ÷ 0.50² = 1.44 × 10⁻⁶ N, with components × 0.40/0.50 = 1.15 × 10⁻⁶ N (x) and × 0.30/0.50 = 8.64 × 10⁻⁷ N (y). Step 4: ΣFx = −1.69 × 10⁻⁶ + 1.15 × 10⁻⁶ = −5.35 × 10⁻⁷ N, ΣFy = 2.00 × 10⁻⁶ + 8.64 × 10⁻⁷ = 2.86 × 10⁻⁶ N, so F = 2.91 × 10⁻⁶ N, 11° to the left of straight up. Common mistake: resolving the diagonal force with the wrong side — the x-component uses the 0.40 m side (cos = 0.40/0.50) — or forgetting that the repulsion from the bottom-right charge points LEFT.', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('94bb7329-f121-5f5e-b3a0-0209e8f8bf2a', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 90, 90, 'Four charges of equal size sit at the corners of a square of side 0.10 m: +5.0 nC at both top corners and −5.0 nC at both bottom corners. A charge of +1.0 nC is placed at the centre of the square, as shown. Calculate the magnitude of the net force on the centre charge, in newtons, and state its direction. Use k = 9.0 × 10⁹ N·m²/C².', 'diagram:coulomb-ch-square-centre', 4, 'numeric'::answer_type, '2.546e-5', 'N', 0.05, false, 'Step 1: each corner is half a diagonal from the centre: r = 0.10√2 ÷ 2 = 0.0707 m, so r² = 0.0050 m². Each corner exerts F = 9.0 × 10⁹ × 5.0 × 10⁻⁹ × 1.0 × 10⁻⁹ ÷ 0.0050 = 9.00 × 10⁻⁶ N. Step 2 (directions): the top two (+) REPEL the centre charge, pushing it diagonally down and away. The bottom two (−) ATTRACT it, pulling diagonally down and towards them. All four forces point at 45° below the horizontal. Step 3: the horizontal components cancel in pairs. Each vertical component is 9.00 × 10⁻⁶ × cos45° = 6.36 × 10⁻⁶ N, all downwards: F = 4 × 6.36 × 10⁻⁶ = 2.55 × 10⁻⁵ N, straight down (towards the negative side). Common mistake: assuming that equal-sized charges around a centre always cancel. They do only when opposite corners carry the SAME sign — here opposite corners have opposite signs, so the forces add.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('a6d3d415-4229-5795-95e8-edf349b0ff78', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 91, 91, 'Calculate the ratio of the electric force to the gravitational force between an electron and a proton, and explain why the answer does not depend on how far apart they are. Use k = 9.0 × 10⁹ N·m²/C², G = 6.67 × 10⁻¹¹ N·m²/kg², e = 1.60 × 10⁻¹⁹ C, electron mass 9.11 × 10⁻³¹ kg and proton mass 1.67 × 10⁻²⁷ kg.', NULL, 4, 'numeric'::answer_type, '2.271e39', NULL, 0.02, false, 'Step 1: write both laws with the same r: Fe = ke²/r² and Fg = Gm_e m_p/r². Step 2: divide — the r² cancels: Fe/Fg = ke²/(Gm_e m_p). Both forces are inverse-square, so their ratio is the same at every separation. Step 3: Fe/Fg = 9.0 × 10⁹ × (1.60 × 10⁻¹⁹)² ÷ (6.67 × 10⁻¹¹ × 9.11 × 10⁻³¹ × 1.67 × 10⁻²⁷) = 2.30 × 10⁻²⁸ ÷ 1.01 × 10⁻⁶⁷ = 2.27 × 10³⁹. In words: between two particles, the electric force is about two thousand billion billion billion billion times stronger than gravity, at any distance — which is why gravity is ignored inside atoms. Common mistake: picking a separation and computing both forces, then losing a power of ten in one of them. Cancelling r² first is quicker and avoids it.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('b8271b39-876a-5392-95d2-4860b9fe9b62', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 92, 92, 'The electric force between an electron and a proton is about 2.3 × 10³⁹ times their gravitational attraction. Yet planets are held in their orbits by gravity, not by electric forces. Which is the best explanation?', NULL, 4, 'multiple_choice'::answer_type, 'Planets and stars carry almost exactly equal amounts of positive and negative charge, so their electric forces cancel, while gravity — always attractive — adds up over every particle', NULL, NULL, false, 'Both forces obey an inverse-square law, so A is false — their ratio does not change with distance. The difference is that charge comes in two signs and mass in only one. A planet contains vast numbers of protons and electrons in almost exactly equal numbers. The electric attractions and repulsions between two such neutral bodies very nearly cancel. Gravity has nothing to cancel it: every kilogram attracts every other kilogram, so it builds up with mass. k is a constant (C is false), and G is about 10²⁰ times SMALLER than k (D is false). Common mistake: concluding that the weaker force must also have the shorter range. Range is not the issue — cancellation is.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('25f9ac9d-c843-58f4-9419-65bc97365c2e', 'b8271b39-876a-5392-95d2-4860b9fe9b62', 'The electric force falls off faster with distance than gravity, so it is negligible over astronomical distances', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('32eea470-1b80-5061-880a-4b9433d124e1', 'b8271b39-876a-5392-95d2-4860b9fe9b62', 'Planets and stars carry almost exactly equal amounts of positive and negative charge, so their electric forces cancel, while gravity — always attractive — adds up over every particle', 'B', true, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('bde258d4-fdd5-5a8f-be43-217444e235c5', 'b8271b39-876a-5392-95d2-4860b9fe9b62', 'Coulomb’s constant k becomes much smaller in the vacuum of space', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('cf94c34c-bb6f-514e-a843-b0667378549a', 'b8271b39-876a-5392-95d2-4860b9fe9b62', 'Gravity is the stronger force for large masses because G is a bigger constant than k', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('10a338a7-a580-5976-a410-06f5d73f3d49', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 93, 93, 'A charged oil drop of mass 2.45 × 10⁻¹⁵ kg is held stationary between two horizontal metal plates. The upper plate is positive and the uniform field between the plates is 5.0 × 10⁴ N/C, as shown. How many excess electrons does the drop carry? Take g = 9.8 N/kg and e = 1.60 × 10⁻¹⁹ C.', 'diagram:coulomb-ch-oil-drop-electrons', 4, 'numeric'::answer_type, '3', NULL, 0.05, false, 'Free-body diagram for the drop: weight mg down and electric force qE up — nothing else (it is stationary, so air resistance is zero). Step 1 (sign): the field points from the positive (top) plate down to the negative plate. The electric force is UPWARDS, opposite to the field, so the charge is negative — the drop has extra electrons. Step 2: balance qE = mg: q = mg/E = 2.45 × 10⁻¹⁵ × 9.8 ÷ 5.0 × 10⁴ = 4.80 × 10⁻¹⁹ C. Step 3: number of electrons = q/e = 4.80 × 10⁻¹⁹ ÷ 1.60 × 10⁻¹⁹ = 3.00, so 3 electrons. A whole number is a good check — charge comes in multiples of e (Millikan’s result). Common mistake: using Coulomb’s law F = kq₁q₂/r² — the plates produce a uniform field, so F = qE. Another is getting the sign wrong: a positive drop would be pushed down.', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('54b36232-193f-53d3-9223-0aec7ef15d7c', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 94, 94, 'An oil drop of mass 3.27 × 10⁻¹⁵ kg is held stationary between horizontal plates in a uniform downward field of 4.0 × 10⁴ N/C. (a) Explain, using a free-body diagram, why the drop is stationary. (b) Calculate the charge on the drop and the number of excess electrons. (c) The drop suddenly picks up one more electron. Calculate its initial acceleration. (d) Calculate the field strength that would hold it stationary again. Enter your answer to (c), in m/s². Take g = 9.8 N/kg and e = 1.60 × 10⁻¹⁹ C.', 'diagram:coulomb-ch-oil-drop-extended', 5, 'numeric'::answer_type, '1.943', 'm/s²', 0.05, false, '(a) Two forces act: weight mg down and electric force qE up. They are equal and opposite, so the resultant force is zero and the drop stays at rest (Newton’s first law). The force is opposite to the downward field, so the drop is negative. (b) q = mg/E = 3.27 × 10⁻¹⁵ × 9.8 ÷ 4.0 × 10⁴ = 8.01 × 10⁻¹⁹ C, which is 5.01 × e, so 5 excess electrons. (c) Now q = 6e = 9.60 × 10⁻¹⁹ C. The electric force rises to qE = 3.84 × 10⁻¹⁴ N but the weight is still 3.20 × 10⁻¹⁴ N, so the resultant is 6.35 × 10⁻¹⁵ N upwards and a = F/m = 6.35 × 10⁻¹⁵ ÷ 3.27 × 10⁻¹⁵ = 1.94 m/s² upwards (at first — air resistance soon builds up as it moves). (d) For balance E = mg/q = 3.20 × 10⁻¹⁴ ÷ 9.60 × 10⁻¹⁹ = 33400 N/C — the field must be REDUCED by a factor 5/6. Common mistake: in (c), using the electric force alone (qE/m) instead of the RESULTANT force, or forgetting that the weight is unchanged.', 8) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('7a4cac36-5948-5896-b89f-368976c15349', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 95, 95, 'A student measures the force F between two equally charged spheres at several separations r and plots F against 1/r². The graph is a straight line through the origin passing through the point (2000 m⁻², 0.0450 N), as shown. (a) What does the straight line through the origin show? (b) What does the gradient represent? (c) Calculate the charge on each sphere, in coulombs. Enter your answer to (c). Use k = 9.0 × 10⁹ N·m²/C².', 'diagram:coulomb-ch-graph-inverse-square', 4, 'numeric'::answer_type, '5e-8', 'C', 0.05, false, '(a) A straight line through the origin means F is directly proportional to 1/r² — an inverse-square law, as Coulomb’s law predicts. (b) Coulomb’s law is F = (kq₁q₂) × (1/r²), which has the form y = mx, so the gradient is kq₁q₂: gradient = 0.0450 N ÷ 2000 m⁻² = 2.25 × 10⁻⁵ N·m². (c) The charges are equal, so kq² = 2.25 × 10⁻⁵ and q = √(2.25 × 10⁻⁵ ÷ 9.0 × 10⁹) = 5.00 × 10⁻⁸ C (50 nC). Common mistake: dividing the gradient by k and forgetting the square root (that gives q², in C²), or reading the gradient as k.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('68a3ab05-d9d2-5392-8bd7-44bd72e91874', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 96, 96, 'In a second experiment the separation is kept fixed and the product of the charges q₁q₂ is varied. The graph of F against q₁q₂ is a straight line through the origin, passing through (5.0 × 10⁻¹⁵ C², 0.0180 N), as shown. Calculate the separation of the charges, in metres. Use k = 9.0 × 10⁹ N·m²/C².', 'diagram:coulomb-ch-graph-product', 4, 'numeric'::answer_type, '0.05', 'm', 0.05, false, 'Step 1: write Coulomb’s law in the form y = mx: F = (k/r²) × (q₁q₂). With r fixed, the gradient is k/r². Step 2: gradient = 0.0180 N ÷ 5.0 × 10⁻¹⁵ C² = 3.60 × 10¹² N/C². Step 3: k/r² = 3.60 × 10¹², so r² = 9.0 × 10⁹ ÷ 3.60 × 10¹² = 0.00250 m² and r = 0.0500 m (5.0 cm). A steeper line would mean a smaller separation, since the gradient is proportional to 1/r². Common mistake: treating the gradient as k, or as k/r instead of k/r², and so forgetting the square root at the end.', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('18f8478b-4083-59dc-b797-38a1f32edded', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 97, 97, 'The graph shows how the force between two fixed charges varies with their separation r. At r = 2.0 cm the force is 0.36 N, as marked. What is the force at r = 6.0 cm?', 'diagram:coulomb-ch-graph-f-vs-r', 4, 'multiple_choice'::answer_type, '0.040 N', NULL, NULL, false, 'The curve is not a straight line, so you cannot read a gradient from it — use the law instead. Step 1: F ∝ 1/r². Tripling r (2.0 → 6.0 cm) divides F by 3² = 9. Step 2: F = 0.36 ÷ 9 = 0.040 N. Where the distractors come from: 0.12 N forgets to square, 0.013 N cubes, and 1.1 N gets the proportion upside down. To TEST the law from data like this, re-plot: F against 1/r² should be a straight line through the origin (the curve of F against r only shows that F falls as r rises). Note also that the cm do not need converting here, because only the ratio 6.0/2.0 matters. Common mistake: assuming F ∝ 1/r because the graph “goes down”.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('0e45214d-608c-5232-9684-c61f068c988c', '18f8478b-4083-59dc-b797-38a1f32edded', '0.12 N', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('2142e8dd-dfaf-5201-9f40-c7f82eb2952b', '18f8478b-4083-59dc-b797-38a1f32edded', '0.040 N', 'B', true, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('85c974af-4e86-5f45-8333-f66c0c44f6f4', '18f8478b-4083-59dc-b797-38a1f32edded', '0.013 N', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('02bdcdbe-e7f5-5fbf-a46e-536a31ddd7fc', '18f8478b-4083-59dc-b797-38a1f32edded', '1.1 N', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('3ea7c8f1-e991-584b-8989-7dbe69d9da35', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 98, 98, 'Two small spheres carry +25 nC and −40 nC, with their centres 2.5 cm apart. What is the magnitude of the force between them? Use k = 9.0 × 10⁹ N·m²/C².', 'diagram:coulomb-two-charges', 4, 'multiple_choice'::answer_type, '0.014 N', NULL, NULL, false, 'Step 1: convert first — 25 nC = 25 × 10⁻⁹ C, 40 nC = 40 × 10⁻⁹ C, 2.5 cm = 0.025 m. Step 2: F = 9.0 × 10⁹ × 25 × 10⁻⁹ × 40 × 10⁻⁹ ÷ 0.025² = 0.014 N. The sign only tells you it is attractive. Where the others come from: 3.6 × 10⁻⁴ N forgets to square r, 1.4 × 10⁻⁶ N leaves r in centimetres, and 14000 N reads nC as µC (10⁻⁶ instead of 10⁻⁹) — a factor of a million. Common mistake: converting only some of the quantities. Put every value into C and m before substituting.', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('6a204f12-66af-5eb7-bf7c-6d9105d99157', '3ea7c8f1-e991-584b-8989-7dbe69d9da35', '3.6 × 10⁻⁴ N', 'A', false, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('73e79f40-529a-51b8-919d-209f37e1a3a1', '3ea7c8f1-e991-584b-8989-7dbe69d9da35', '0.014 N', 'B', true, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('6ef7288e-ddb2-5961-b2b8-ab7720e62ff3', '3ea7c8f1-e991-584b-8989-7dbe69d9da35', '1.4 × 10⁻⁶ N', 'C', false, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES ('dd31dee0-4ebb-5eb5-ab4b-04106ac2785d', '3ea7c8f1-e991-584b-8989-7dbe69d9da35', '14000 N', 'D', false, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_tolerance, answer_sign_sensitive, explanation, points) VALUES ('7839b4b8-79bb-5108-85ff-2a0b9d1109ff', '7137f560-2406-4a69-9099-4c845ef53ea8', 'c6c1d1f5-1c6b-4ab4-a15b-beea25426304', 'igcse', NULL, NULL, 99, 99, 'Two small metal spheres, each of radius 1.0 cm and each carrying +30 nC, are placed so that the GAP between their surfaces is 3.0 cm, as shown. Treating each sphere as a point charge at its centre, what is the force between them? Use k = 9.0 × 10⁹ N·m²/C².', 'diagram:coulomb-ch-mcq-centre-distance', 4, 'multiple_choice'::answer_type, '0.0032 N', NULL, NULL, false, 'Step 1: Coulomb’s law uses the distance between the CENTRES: r = 1.0 + 3.0 + 1.0 = 5.0 cm = 0.050 m. Step 2: F = 9.0 × 10⁹ × (30 × 10⁻⁹)² ÷ 0.050² = 0.0032 N (repulsive). The others: 0.0090 N uses the gap alone, 0.0051 N adds only one radius, and 1.6 × 10⁻⁴ N forgets to square r. Evaluate: spheres this close are only approximately point charges — the charges repel each other towards the far sides, so the true force is a little less than this. Common mistake: measuring r between the surfaces. The same applies to the hanging-ball questions: r is centre to centre.', 3) ON CONFLICT (id) DO NOTHING;
